∀ (c : ℝ) {x : ↥(MeasureTheory.Lp Breakdown.Space 2 Breakdown.Coercive.Internal.TestDensityProof.periodMeasure)},
  x ∈ {f | ∃ ψ, Breakdown.IsPeriodicTestField ψ ∧ Breakdown.Coercive.Internal.TestDensityProof.toL2 ψ = f} →
    c • x ∈ {f | ∃ ψ, Breakdown.IsPeriodicTestField ψ ∧ Breakdown.Coercive.Internal.TestDensityProof.toL2 ψ = f}

Breakdown.Coercive.AxialRotationHolds →
  Breakdown.Coercive.PerturbationLocalSquareIntegrabilityHolds →
    ∀ {Γ : Set Breakdown.Symmetry} {P : ℝ} {v : ℝ → Breakdown.Space → Breakdown.Space}
      {G : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space}
      {H : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space →L[ℝ] Breakdown.Space}
      {g : ℝ → Breakdown.Space → Breakdown.Space},
      Breakdown.IsPerturbation Γ P v G H g →
        ∀ᵐ (y : Breakdown.Space),
          MeasureTheory.MemLp (fun p => v p.1 (Breakdown.axialRot p.2 y)) 2
            Breakdown.Coercive.Internal.ModeRotation.boxMeasure

∀ {C : Type} {nE nM : ℕ} {m : Breakdown.PieceWeights C nE nM} {P : ℝ} {h : Breakdown.HarmonicBounds}
  {w : Breakdown.Space → ℝ} {W : ℝ → Breakdown.Space → Breakdown.Space} {w₀ epsSup epsGradSup ratio : ℝ}
  {v : ℝ → Breakdown.Space → Breakdown.Space},
  Breakdown.Coercive.Internal.SmoothPieceEpsCore.CoreSetting m P h w W w₀ epsSup epsGradSup ratio v →
    m.IsAdmissible P h w W w₀ epsSup epsGradSup ratio

∀ {C : Type} {nE nM : ℕ} {m : Breakdown.PieceWeights C nE nM} {P : ℝ} {h : Breakdown.HarmonicBounds}
  {w : Breakdown.Space → ℝ} {W : ℝ → Breakdown.Space → Breakdown.Space} {w₀ epsSup epsGradSup ratio : ℝ}
  {v : ℝ → Breakdown.Space → Breakdown.Space},
  Breakdown.Coercive.Internal.SmoothPieceEpsCore.CoreSetting m P h w W w₀ epsSup epsGradSup ratio v →
    ∀ (β : Fin nE), ∀ ι ∈ (m.epsP β).modes, -ι ∉ (m.epsP β).modes

∀ {C : Type} {nE nM : ℕ} {m : Breakdown.PieceWeights C nE nM} {P : ℝ} {h : Breakdown.HarmonicBounds}
  {w : Breakdown.Space → ℝ} {W : ℝ → Breakdown.Space → Breakdown.Space} {w₀ epsSup epsGradSup ratio : ℝ}
  {v : ℝ → Breakdown.Space → Breakdown.Space},
  Breakdown.Coercive.Internal.SmoothPieceEpsCore.CoreSetting m P h w W w₀ epsSup epsGradSup ratio v →
    ∃ D, ∀ (σ : ℝ) (y : Breakdown.Space), ∀ j ≤ 2, ‖iteratedFDeriv ℝ j (W σ) y‖ ≤ D / (1 + ‖y‖) ^ (j + 1)

∀ {α : Type u_1} {E : Type u_2} {ι : Type u_3} [inst : MeasurableSpace α] {μ : MeasureTheory.Measure α}
  [inst_1 : NormedAddCommGroup E] {p : ENNReal} (s : Finset ι) (f : ι → ↥(MeasureTheory.Lp E p μ)),
  ↑↑(∑ i ∈ s, f i) =ᵐ[μ] ∑ i ∈ s, ↑↑(f i)

∀ {C : Type} {nE nM : ℕ} {m : Breakdown.PieceWeights C nE nM} {P : ℝ} {h : Breakdown.HarmonicBounds}
  {w : Breakdown.Space → ℝ} {W : ℝ → Breakdown.Space → Breakdown.Space} {w₀ epsSup epsGradSup ratio : ℝ}
  {v : ℝ → Breakdown.Space → Breakdown.Space},
  Breakdown.Coercive.Internal.SmoothPieceEpsCore.CoreSetting m P h w W w₀ epsSup epsGradSup ratio v →
    ∀ (σ : ℝ) (y : Breakdown.Space), Breakdown.divergenceAt (W σ) y = 0

∀ {C : Type} {nE nM : ℕ} {m : Breakdown.PieceWeights C nE nM} {P : ℝ} {h : Breakdown.HarmonicBounds}
  {w : Breakdown.Space → ℝ} {W : ℝ → Breakdown.Space → Breakdown.Space} {w₀ epsSup epsGradSup ratio : ℝ}
  {v : ℝ → Breakdown.Space → Breakdown.Space},
  Breakdown.Coercive.Internal.SmoothPieceEpsCore.CoreSetting m P h w W w₀ epsSup epsGradSup ratio v →
    ∃ B, ∀ (y : Breakdown.Space), w y ≤ B

∀ {C : Type} {nE nM : ℕ} {m : Breakdown.PieceWeights C nE nM} {P : ℝ} {h : Breakdown.HarmonicBounds}
  {w : Breakdown.Space → ℝ} {W : ℝ → Breakdown.Space → Breakdown.Space} {w₀ epsSup epsGradSup ratio : ℝ}
  {v : ℝ → Breakdown.Space → Breakdown.Space},
  Breakdown.Coercive.Internal.SmoothPieceEpsCore.CoreSetting m P h w W w₀ epsSup epsGradSup ratio v →
    ContDiff ℝ 2 fun z => W z.1 z.2

Breakdown.Coercive.AxialRotationHolds →
  ∀ {Γ : Set Breakdown.Symmetry} {P : ℝ} {v : ℝ → Breakdown.Space → Breakdown.Space}
    {G : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space}
    {H : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space →L[ℝ] Breakdown.Space}
    {g : ℝ → Breakdown.Space → Breakdown.Space},
    Breakdown.IsPerturbation Γ P v G H g →
      ∀ (k : Fin 3),
        ∀ᵐ (y : Breakdown.Space),
          MeasureTheory.MemLp (fun p => (G p.1 (Breakdown.axialRot p.2 y)) (Breakdown.unitVector k)) 2
            Breakdown.Coercive.Internal.ModeRotation.boxMeasure

∀ {C : Type} {nE nM : ℕ} {m : Breakdown.PieceWeights C nE nM} {P : ℝ} {h : Breakdown.HarmonicBounds}
  {w : Breakdown.Space → ℝ} {W : ℝ → Breakdown.Space → Breakdown.Space} {w₀ epsSup epsGradSup ratio : ℝ}
  {v : ℝ → Breakdown.Space → Breakdown.Space},
  Breakdown.Coercive.Internal.SmoothPieceEpsCore.CoreSetting m P h w W w₀ epsSup epsGradSup ratio v →
    Breakdown.Coercive.IsSmoothPerturbation P v

∀ {C : Type} {nE nM : ℕ} {m : Breakdown.PieceWeights C nE nM} {P : ℝ} {h : Breakdown.HarmonicBounds}
  {w : Breakdown.Space → ℝ} {W : ℝ → Breakdown.Space → Breakdown.Space} {w₀ epsSup epsGradSup ratio : ℝ}
  {v : ℝ → Breakdown.Space → Breakdown.Space},
  Breakdown.Coercive.Internal.SmoothPieceEpsCore.CoreSetting m P h w W w₀ epsSup epsGradSup ratio v →
    Breakdown.IsTimePeriodic W
